export function retryDelay(attempt, baseMs, capMs) {
  if (!Number.isSafeInteger(attempt) || attempt < 1 || !Number.isSafeInteger(baseMs) || baseMs < 1 || !Number.isSafeInteger(capMs) || capMs < baseMs) throw new RangeError('retry');
  return Math.min(capMs, baseMs * 2 ** (attempt - 1));
}

